def compute(vars):
    due_lease = vars["v1"]
    total_due = vars["v2"]

    try:
        percentage = due_lease / total_due * 100
    except ZeroDivisionError:
        return None

    return {
        "value": percentage,
        "trace": {
            "due_lease": due_lease,
            "total_due": total_due,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
